<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root.root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/empty</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 修改用户组</span></span>
